// A 64x64 blue-noise threshold tile (void-and-cluster, sigma 1.5, seed 7),
// generated by scripts/dither_engine.py so the pass and the footage script
// make the same grain. Ranks 0..4095 as little-endian uint16, base64.
// Regenerate: see the blue-noise section of docs/primitives/dither-pass.md.

const DATA = "";

let tile: Float32Array | null = null;

/** Thresholds in (0, 1), row-major, 64x64. */
export function blueNoise64(): Float32Array {
  if (tile) return tile;
  const bytes = Uint8Array.from(atob(DATA), (c) => c.charCodeAt(0));
  const ranks = new Uint16Array(bytes.buffer);
  tile = new Float32Array(4096);
  for (let i = 0; i < 4096; i++) tile[i] = (ranks[i] + 0.5) / 4096;
  return tile;
}
